"use client";
import React, { useEffect, useState } from "react";
import { collection, getDocs, updateDoc, deleteDoc, doc } from "firebase/firestore";
import { db } from "../../utils/firebase";

export default function AdminGuestPosts() {
  const [posts, setPosts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    async function fetchPosts() {
      try {
        const snap = await getDocs(collection(db, "guest_posts"));
        setPosts(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      } catch (e) {
        setError("Failed to load guest posts.");
      }
      setLoading(false);
    }
    fetchPosts();
  }, []);

  async function handleApprove(id: string) {
    await updateDoc(doc(db, "guest_posts", id), { status: "approved" });
    setPosts(posts => posts.map(p => p.id === id ? { ...p, status: "approved" } : p));
  }

  async function handleReject(id: string) {
    await updateDoc(doc(db, "guest_posts", id), { status: "rejected" });
    setPosts(posts => posts.map(p => p.id === id ? { ...p, status: "rejected" } : p));
  }

  async function handleDelete(id: string) {
    await deleteDoc(doc(db, "guest_posts", id));
    setPosts(posts => posts.filter(p => p.id !== id));
  }

  return (
    <div className="min-h-screen flex flex-col items-center bg-[#f7f8fa] px-4 py-8">
      <div className="w-full max-w-3xl bg-white rounded-xl shadow p-8">
        <h1 className="text-3xl font-bold text-[#232946] mb-6 text-center">Guest Post Submissions</h1>
        {loading && <div className="text-[#3CB371] text-center">Loading...</div>}
        {error && <div className="text-red-600 text-center mb-4">{error}</div>}
        <ul className="space-y-6">
          {posts.length === 0 && !loading && (
            <li className="text-[#888] text-center">No guest posts found.</li>
          )}
          {posts.map(post => (
            <li key={post.id} className="bg-[#f7f8fa] rounded-lg shadow p-4">
              <div className="flex flex-col gap-2">
                <div className="font-bold text-lg text-[#232946]">{post.title}</div>
                <div className="text-sm text-[#444]">{post.content}</div>
                <div className="text-xs text-[#888]">By {post.author} ({post.email})</div>
                <div className="text-xs text-[#888]">Category: {post.category || "Uncategorized"}</div>
                <div className="text-xs text-[#888]">Status: <span className={post.status === "approved" ? "text-green-600" : post.status === "rejected" ? "text-red-600" : "text-yellow-600"}>{post.status}</span></div>
                <div className="flex gap-2 mt-2">
                  {post.status === "pending" && (
                    <>
                      <button className="px-3 py-1 rounded bg-[#3CB371] text-white font-bold" onClick={() => handleApprove(post.id)}>Approve</button>
                      <button className="px-3 py-1 rounded bg-red-100 text-red-600 font-bold" onClick={() => handleReject(post.id)}>Reject</button>
                    </>
                  )}
                  <button className="px-3 py-1 rounded bg-gray-200 text-[#232946] font-bold" onClick={() => handleDelete(post.id)}>Delete</button>
                </div>
              </div>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

"use client";
import React, { useEffect, useState } from "react";
import { collection, getDocs, updateDoc, deleteDoc, doc } from "firebase/firestore";
import { db } from "../../../utils/firebase";
import AdminLayout from "@/components/admin/AdminLayout";

export default function AdminGuestPosts() {
  const [posts, setPosts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    async function fetchPosts() {
      try {
        const snap = await getDocs(collection(db, "guest_posts"));
        setPosts(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      } catch (_e) {
        setError("Failed to load guest posts.");
      }
      setLoading(false);
    }
    fetchPosts();
  }, []);

  async function handleApprove(id: string) {
    await updateDoc(doc(db, "guest_posts", id), { status: "approved" });
    setPosts(posts => posts.map(p => p.id === id ? { ...p, status: "approved" } : p));
  }

  async function handleReject(id: string) {
    await updateDoc(doc(db, "guest_posts", id), { status: "rejected" });
    setPosts(posts => posts.map(p => p.id === id ? { ...p, status: "rejected" } : p));
  }

  async function handleDelete(id: string) {
    await deleteDoc(doc(db, "guest_posts", id));
    setPosts(posts => posts.filter(p => p.id !== id));
  }

  return (
    <AdminLayout>
      <div className="w-full">
        <h1 className="text-3xl font-bold text-[#232946] mb-6">Guest Post Submissions</h1>
        {loading && <div className="text-[#3CB371] text-center">Loading...</div>}
        {error && <div className="text-red-600 text-center mb-4">{error}</div>}
        <div className="overflow-x-auto">
          <table className="w-full border border-gray-200 rounded-lg">
            <thead className="bg-[#f7f8fa]">
              <tr>
                <th className="px-4 py-2 text-left text-sm font-bold text-[#232946] border-b">Title</th>
                <th className="px-4 py-2 text-left text-sm font-bold text-[#232946] border-b">Content</th>
                <th className="px-4 py-2 text-left text-sm font-bold text-[#232946] border-b">Author</th>
                <th className="px-4 py-2 text-left text-sm font-bold text-[#232946] border-b">Email</th>
                <th className="px-4 py-2 text-left text-sm font-bold text-[#232946] border-b">Category</th>
                <th className="px-4 py-2 text-left text-sm font-bold text-[#232946] border-b">Status</th>
                <th className="px-4 py-2 text-left text-sm font-bold text-[#232946] border-b">Actions</th>
              </tr>
            </thead>
            <tbody>
              {posts.length === 0 && !loading && (
                <tr>
                  <td colSpan={7} className="text-[#888] text-center py-6">No guest posts found.</td>
                </tr>
              )}
              {posts.map(post => (
                <tr key={post.id} className="border-b">
                  <td className="px-4 py-2 text-sm font-semibold text-[#232946] max-w-[180px] truncate">{post.title}</td>
                  <td className="px-4 py-2 text-sm text-[#444] max-w-[320px] truncate">{post.content}</td>
                  <td className="px-4 py-2 text-xs text-[#888]">{post.author}</td>
                  <td className="px-4 py-2 text-xs text-[#888]">{post.email}</td>
                  <td className="px-4 py-2 text-xs text-[#888]">{post.category || "Uncategorized"}</td>
                  <td className="px-4 py-2 text-xs">
                    <span className={post.status === "approved" ? "text-green-600 font-bold" : post.status === "rejected" ? "text-red-600 font-bold" : "text-yellow-600 font-bold"}>{post.status}</span>
                  </td>
                  <td className="px-4 py-2 text-xs">
                    <div className="flex gap-2">
                      {post.status === "pending" && (
                        <>
                          <button className="px-3 py-1 rounded bg-[#3CB371] text-white font-bold text-xs" onClick={() => handleApprove(post.id)}>Approve</button>
                          <button className="px-3 py-1 rounded bg-red-100 text-red-600 font-bold text-xs" onClick={() => handleReject(post.id)}>Reject</button>
                        </>
                      )}
                      <button className="px-3 py-1 rounded bg-gray-200 text-[#232946] font-bold text-xs" onClick={() => handleDelete(post.id)}>Delete</button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </AdminLayout>
  );
}

"use client";

import AdminLayout from '../../components/admin/AdminLayout';
import BlogAnalytics from '../../components/admin/BlogAnalytics';
import { dashboardCards } from '../../components/admin/dashboardCards';
import WelcomeCard from '../../components/admin/WelcomeCard';
import { useEffect, useState } from 'react';
import { collection, getDocs, query, orderBy, limit } from 'firebase/firestore';
import { db } from '../../utils/firebase';
import Image from "next/image";
import { cloudinaryUrl } from '../../utils/cloudinary';

export default function AdminDashboard() {
  type StatKey = 'posts' | 'authors' | 'categories' | 'views';
  const [stats, setStats] = useState<{ posts: number; authors: number; categories: number; views: number }>({ posts: 0, authors: 0, categories: 0, views: 0 });
  const [loading, setLoading] = useState(true);
  const [recentBlogs, setRecentBlogs] = useState<any[]>([]);
  const [topPosts, setTopPosts] = useState<any[]>([]);
  const [gaSummary, setGaSummary] = useState<any>(null);

  useEffect(() => {
    async function fetchStats() {
      const postsSnap = await getDocs(collection(db, 'posts'));
      const authorsSnap = await getDocs(collection(db, 'authors'));
      const categoriesSnap = await getDocs(collection(db, 'categories'));
      const totalViews = postsSnap.docs.reduce((sum, doc) => sum + (doc.data().views || 0), 0);
      setStats({
        posts: postsSnap.size,
        authors: authorsSnap.size,
        categories: categoriesSnap.size,
        views: totalViews,
      });
      setLoading(false);
    }
    async function fetchRecentBlogs() {
      try {
        const q = query(collection(db, 'posts'), orderBy('date', 'desc'), limit(5));
        const snap = await getDocs(q);
        if (snap.empty) {
          // Fallback: fetch without orderBy if no posts or no date field
          const fallbackSnap = await getDocs(collection(db, 'posts'));
          setRecentBlogs(fallbackSnap.docs.map(d => ({ id: d.id, ...d.data() })));
        } else {
          setRecentBlogs(snap.docs.map(d => ({ id: d.id, ...d.data() })));
        }
      } catch (_e) {
          // Fallback: fetch without orderBy if error (e.g., missing date field)
          const fallbackSnap = await getDocs(collection(db, 'posts'));
          setRecentBlogs(fallbackSnap.docs.map(d => ({ id: d.id, ...d.data() })));
        }
    }
    async function fetchTopPosts() {
      const q = query(collection(db, 'posts'), orderBy('views', 'desc'), limit(5));
      const snap = await getDocs(q);
      setTopPosts(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    }
    async function fetchGaSummary() {
      try {
        const res = await fetch('/api/analytics/summary');
        const json = await res.json();
        setGaSummary(json.data);
      } catch (e) {
        setGaSummary(null);
      }
    }
    fetchStats();
    fetchRecentBlogs();
    fetchTopPosts();
    fetchGaSummary();
  }, []);

  return (
    <AdminLayout>
      <div className="max-w-7xl mx-auto px-2 md:px-0">
        <WelcomeCard name="Admin" stats={{ posts: stats.posts, subscribers: 99 }} />
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          {dashboardCards.map(card => (
            <div key={card.key} className={`rounded-2xl shadow flex flex-col items-center justify-center p-6 ${card.color} border border-[#eaf0f6]`}>
              <div className="mb-2">{card.icon}</div>
              <div className="text-2xl font-bold text-[#232946]">{loading ? '...' : stats[card.key as StatKey]}</div>
              <div className="text-base text-[#3CB371] font-semibold mt-1">{card.title}</div>
            </div>
          ))}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {/* Analytics and Visitors Chart */}
          <div className="col-span-2">
            <div className="mb-8">
              <BlogAnalytics />
              {/* Google Analytics Summary */}
              <div className="bg-[#f7f8fa] rounded-xl p-4 mt-6">
                <h3 className="text-lg font-bold text-[#232946] mb-2">Google Analytics (Last 30 Days)</h3>
                {gaSummary ? (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <div className="font-semibold text-[#232946]">Active Users:</div>
                      <div className="text-[#3CB371] text-xl font-bold">{gaSummary.totals?.[0]?.metricValues?.[0]?.value || '-'}</div>
                    </div>
                    <div>
                      <div className="font-semibold text-[#232946]">Sessions:</div>
                      <div className="text-[#3CB371] text-xl font-bold">{gaSummary.totals?.[0]?.metricValues?.[1]?.value || '-'}</div>
                    </div>
                    <div>
                      <div className="font-semibold text-[#232946]">Bounce Rate:</div>
                      <div className="text-[#3CB371] text-xl font-bold">{gaSummary.totals?.[0]?.metricValues?.[2]?.value || '-'}</div>
                    </div>
                    <div>
                      <div className="font-semibold text-[#232946]">Avg. Session Duration:</div>
                      <div className="text-[#3CB371] text-xl font-bold">{gaSummary.totals?.[0]?.metricValues?.[3]?.value || '-'}</div>
                    </div>
                    <div>
                      <div className="font-semibold text-[#232946]">Page Views:</div>
                      <div className="text-[#3CB371] text-xl font-bold">{gaSummary.totals?.[0]?.metricValues?.[4]?.value || '-'}</div>
                    </div>
                  </div>
                ) : (
                  <div className="text-[#888]">Loading Google Analytics data...</div>
                )}
                {/* Top Countries */}
                {gaSummary?.rows && (
                  <div className="mt-6">
                    <div className="font-bold text-[#232946] mb-2">Top Countries</div>
                    <ul className="text-sm">
                      {gaSummary.rows.filter((row: any) => row.dimensionValues?.[0]?.value).slice(0, 5).map((row: any, idx: number) => (
                        <li key={idx} className="flex justify-between border-b py-1">
                          <span>{row.dimensionValues?.[0]?.value}</span>
                          <span className="text-[#3CB371]">{row.metricValues?.[0]?.value}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
                {/* Top Devices */}
                {gaSummary?.rows && (
                  <div className="mt-6">
                    <div className="font-bold text-[#232946] mb-2">Top Devices</div>
                    <ul className="text-sm">
                      {gaSummary.rows.filter((row: any) => row.dimensionValues?.[1]?.value).slice(0, 5).map((row: any, idx: number) => (
                        <li key={idx} className="flex justify-between border-b py-1">
                          <span>{row.dimensionValues?.[1]?.value}</span>
                          <span className="text-[#3CB371]">{row.metricValues?.[0]?.value}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
                {/* Top Pages */}
                {gaSummary?.rows && (
                  <div className="mt-6">
                    <div className="font-bold text-[#232946] mb-2">Top Pages</div>
                    <ul className="text-sm">
                      {gaSummary.rows.filter((row: any) => row.dimensionValues?.[2]?.value).slice(0, 5).map((row: any, idx: number) => (
                        <li key={idx} className="flex justify-between border-b py-1">
                          <span>{row.dimensionValues?.[2]?.value}</span>
                          <span className="text-[#3CB371]">{row.metricValues?.[0]?.value}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
                {/* Top Sources */}
                {gaSummary?.rows && (
                  <div className="mt-6">
                    <div className="font-bold text-[#232946] mb-2">Top Sources</div>
                    <ul className="text-sm">
                      {gaSummary.rows.filter((row: any) => row.dimensionValues?.[3]?.value).slice(0, 5).map((row: any, idx: number) => (
                        <li key={idx} className="flex justify-between border-b py-1">
                          <span>{row.dimensionValues?.[3]?.value}</span>
                          <span className="text-[#3CB371]">{row.metricValues?.[0]?.value}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </div>
            </div>
            {/* Top Posts */}
            <div className="bg-white rounded-2xl shadow p-6 border border-[#eaf0f6] mt-8">
              <h3 className="text-lg font-bold text-[#232946] mb-4">Top Posts (by Views)</h3>
              <ul className="space-y-4">
                {topPosts.map(post => (
                  <li key={post.id} className="flex items-center gap-3">
                    <Image
                      src={cloudinaryUrl(post.image || '/file.svg', 96) || '/file.svg'}
                      alt={post.title}
                      width={48}
                      height={48}
                      className="rounded-lg object-cover bg-[#eaf0f6]"
                    />
                    <div className="flex-1">
                      <div className="font-semibold text-[#232946] text-base truncate">{post.title}</div>
                      <div className="text-xs text-[#3CB371] flex gap-2 mt-1">
                        <span>{post.date}</span>
                        <span>• {post.views || 0} views</span>
                      </div>
                    </div>
                    <a href={`/posts/${post.slug}`} className="text-[#3CB371] text-xs font-bold hover:underline">View</a>
                  </li>
                ))}
              </ul>
            </div>
          </div>
          {/* Recent Blogs */}
          <div className="bg-white rounded-2xl shadow p-6 border border-[#eaf0f6]">
            <h3 className="text-lg font-bold text-[#232946] mb-4">Recent Blogs</h3>
            <ul className="space-y-4">
              {recentBlogs.length === 0 && (
                <li className="text-[#888]">No recent blogs found. Make sure your posts have a <b>date</b> field.</li>
              )}
              {recentBlogs.map(blog => (
                <li key={blog.id} className="flex items-start gap-3 py-2">
                  <Image
                    src={cloudinaryUrl(blog.image || '/file.svg', 96) || '/file.svg'}
                    alt={blog.title}
                    width={48}
                    height={48}
                    className="rounded-lg object-cover bg-[#eaf0f6] flex-shrink-0"
                  />
                  <div className="flex-1 min-w-0 flex flex-col justify-between">
                    <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-1">
                      <div className="font-semibold text-[#232946] text-base break-words line-clamp-2 max-w-full">{blog.title}</div>
                      <a href={`/posts/${blog.slug}`} className="text-[#3CB371] text-xs font-bold hover:underline sm:ml-4 sm:self-start">View</a>
                    </div>
                    <div className="text-xs text-[#3CB371] flex gap-2 mt-1">
                      <span>{blog.date || <span className='text-[#888]'>No date</span>}</span>
                      <span>• {blog.views || 0} views</span>
                    </div>
                  </div>
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>
    </AdminLayout>
  );
}

"use client";
import { useState, useEffect } from "react";
import Image from 'next/image';
import { collection, addDoc, getDocs, updateDoc, deleteDoc, doc, writeBatch } from "firebase/firestore";
import { db } from "../../../utils/firebase";
import PostForm from "../../../components/admin/PostForm";

export default function PostCrud() {
  const [posts, setPosts] = useState<any[]>([]);
  const [editing, setEditing] = useState<any | null>(null);
  const [showForm, setShowForm] = useState(false);

  async function fetchPosts() {
    const [snap, snapHindi] = await Promise.all([
      getDocs(collection(db, "posts")),
      getDocs(collection(db, "posts_hindi")),
    ]);
    const posts = snap.docs.map(d => ({ id: d.id, ...d.data(), lang: 'en' }));
    const postsHindi = snapHindi.docs.map(d => ({ id: d.id, ...d.data(), lang: 'hi' }));
    setPosts([...posts, ...postsHindi]);
  }

  useEffect(() => { fetchPosts(); }, []);

  async function handleCreate(data: any) {
    // Remove id if present (for new posts)
    const { id, ...rest } = data;
    // Determine if Hindi post by category
    const cats = Array.isArray(rest.category) ? rest.category : [rest.category];
    const isHindi = cats.some((cat: string) => cat === 'हिंदी' || cat === 'Hindi');
    const collectionName = isHindi ? 'posts_hindi' : 'posts';
    // Use client-side addDoc for both collections (user must be authenticated)
    const docRef = await addDoc(collection(db, collectionName), rest);
    setShowForm(false);
    fetchPosts();
    // notify subscribers about the new post (best-effort, only for non-Hindi)
    if (!isHindi) {
      try {
        const slug = rest.slug || '';
        const origin = typeof window !== 'undefined' ? window.location.origin : '';
        const url = origin ? `${origin}/posts/${slug}` : `/posts/${slug}`;
        await fetch('/api/notify-post', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: rest.title, excerpt: rest.excerpt || '', url }) });
        console.log('Notify sent for new post');
      } catch (err) {
        console.error('Notify failed', err);
      }
    }
  }

  async function handleUpdate(data: any) {
    if (!editing) return;
    // Don't update id field in Firestore
    const { id, ...rest } = data;
    await updateDoc(doc(db, "posts", editing.id), rest);
    setEditing(null);
    setShowForm(false);
    fetchPosts();
  }

  async function handleDelete(id: string) {
    await deleteDoc(doc(db, "posts", id));
    fetchPosts();
  }

  async function handleFeature(postId: string) {
    // Unset 'featured' on all posts, set it on the selected one
    const snap = await getDocs(collection(db, "posts"));
    const batch = writeBatch(db);
    snap.docs.forEach(docSnap => {
      const isTarget = docSnap.id === postId;
      batch.update(doc(db, "posts", docSnap.id), { featured: isTarget });
    });
    await batch.commit();
    fetchPosts();
  }

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-[#232946]">Posts</h2>
        <button onClick={() => { setEditing(null); setShowForm(true); }} className="bg-[#3CB371] text-white px-4 py-2 rounded">Add Post</button>
      </div>
      {showForm && (
        <PostForm
          onSubmit={editing ? handleUpdate : handleCreate}
          initialData={editing}
        />
      )}
      <div className="mt-8 overflow-x-auto">
        <table className="w-full border text-[#232946] min-w-max">
          <thead>
            <tr className="bg-[#f7f8fa] text-[#232946]">
              <th className="p-2 border font-semibold">Title</th>
              <th className="p-2 border font-semibold">Image</th>
              <th className="p-2 border font-semibold">Actions</th>
              <th className="p-2 border font-semibold">Feature</th>
            </tr>
          </thead>
          <tbody>
            {posts.map(post => (
              <tr key={post.id} className="text-[#232946]">
                <td className="p-2 border">{post.title}</td>
                <td className="p-2 border">{post.image && <Image src={post.image} alt={post.title || ''} width={48} height={48} className="rounded" />}</td>
                <td className="p-2 border">
                  <button onClick={() => { setEditing(post); setShowForm(true); }} className="text-blue-600 mr-2">Edit</button>
                  <button onClick={() => handleDelete(post.id)} className="text-red-600">Delete</button>
                </td>
                <td className="p-2 border text-center">
                  {post.featured ? (
                    <span className="text-green-600 font-bold">Featured</span>
                  ) : (
                    <button onClick={() => handleFeature(post.id)} className="bg-[#3CB371] text-white px-3 py-1 rounded text-xs">Make Featured</button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { NextRequest, NextResponse } from "next/server";
import admin from "../../../../utils/firebaseAdmin";
import { Review } from "../../../../types/review";

export async function GET(req: NextRequest) {
  try {
    if (!admin.apps.length) {
      return NextResponse.json({ error: "Firebase not initialized" }, { status: 500 });
    }

    const db = admin.firestore();
    const snapshot = await db
      .collection("reviews")
      .orderBy("createdAt", "desc")
      .get();

    const reviews: Review[] = [];
    snapshot.forEach((doc) => {
      reviews.push({ id: doc.id, ...doc.data() } as Review);
    });

    return NextResponse.json({ reviews }, { status: 200 });
  } catch (error: any) {
