"use client";

import React, { useState } from "react";
import { PayPalScriptProvider, PayPalButtons, usePayPalScriptReducer } from "@paypal/react-paypal-js";
import { useRouter } from "next/navigation";

interface PayPalCheckoutButtonProps {
  planId: string;
  customerEmail: string;
  customerName?: string;
  discountCode?: string;
}

function PayPalButtonsWrapper({
  planId,
  customerEmail,
  customerName,
  discountCode,
}: PayPalCheckoutButtonProps) {
  const [{ isPending }] = usePayPalScriptReducer();
  const [error, setError] = useState<string | null>(null);
  const router = useRouter();

  return (
    <>
      {error && (
        <div className="mb-4 p-4 text-sm text-red-700 bg-red-100 rounded-lg">
          {error}
        </div>
      )}

      {isPending && (
        <div className="w-full flex flex-col space-y-4 animate-pulse">
          <div className="h-12 bg-gray-200 rounded-md w-full"></div>
          <div className="h-12 bg-gray-200 rounded-md w-full"></div>
        </div>
      )}

      <div className={isPending ? "hidden" : "block"}>
        <PayPalButtons
          style={{ layout: "vertical", shape: "rect" }}
          createOrder={async () => {
            setError(null);
            try {
              const response = await fetch("/api/paypal/create-order", {
                method: "POST",
                headers: {
                  "Content-Type": "application/json",
                },
                body: JSON.stringify({
                  planId,
                  customerEmail,
                  customerName,
                  discountCode,
                }),
              });

              const orderData = await response.json();

              if (!response.ok) {
                const errorDetail = orderData?.error;
                throw new Error(errorDetail || "Could not create order");
              }

              if (orderData.orderId) {
                return orderData.orderId;
              } else {
                throw new Error("Invalid response from server");
              }
            } catch (err: any) {
              setError(err.message || "Failed to initiate PayPal checkout.");
              throw err; // Stop checkout flow
            }
          }}
          onApprove={async (data, actions) => {
            try {
              const response = await fetch("/api/paypal/capture-order", {
                method: "POST",
                headers: {
                  "Content-Type": "application/json",
                },
                body: JSON.stringify({
                  orderId: data.orderID,
                }),
              });

              const captureData = await response.json();

              if (!response.ok) {
                throw new Error(captureData.error || "Failed to capture payment.");
              }

              // Payment successful! Navigate to success page
              router.push(`/payment/success?orderId=${data.orderID}`);
            } catch (err: any) {
              setError(err.message || "Failed to finalize the payment.");
            }
          }}
          onCancel={() => {
            router.push(`/payment/failed?planId=${planId}`);
          }}
          onError={(err) => {
            console.error("PayPal Error:", err);
            setError("An unexpected error occurred with PayPal.");
            router.push(`/payment/failed?planId=${planId}`);
          }}
        />
      </div>
    </>
  );
}

export default function PayPalCheckoutButton(props: PayPalCheckoutButtonProps) {
  const clientId = process.env.NEXT_PUBLIC_PAYPAL_CLIENT_ID || "";

  if (!clientId) {
    return <div className="text-red-500 font-bold">PayPal Client ID is missing!</div>;
  }

  const initialOptions = {
    clientId,
    currency: "USD",
    intent: "capture",
  };

  return (
    <div className="w-full">
      <PayPalScriptProvider options={initialOptions}>
        <PayPalButtonsWrapper {...props} />
      </PayPalScriptProvider>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { useRouter } from "next/navigation";

interface LicenseActionsProps {
  licenseId: string;
  status: string;
  customerEmail: string;
}

export default function LicenseActions({ licenseId, status, customerEmail }: LicenseActionsProps) {
  const [isLoading, setIsLoading] = useState(false);
  const router = useRouter();

  const handleAction = async (endpoint: string, actionName: string) => {
    if (!confirm(`Are you sure you want to ${actionName} this license?`)) return;

    setIsLoading(true);
    try {
      const res = await fetch(`/api/admin/licenses/${endpoint}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ licenseId }),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Action failed");

      alert(`Success: ${actionName} completed.`);
      router.refresh();
    } catch (err: any) {
      alert(`Error: ${err.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-wrap gap-2">
      {status !== "REVOKED" && (
        <button
          onClick={() => handleAction("revoke", "revoke")}
          disabled={isLoading}
          className="bg-red-50 text-red-600 border border-red-200 hover:bg-red-100 font-semibold px-3 py-1.5 rounded-md text-xs transition-colors disabled:opacity-50"
        >
          Revoke
        </button>
      )}

      <button
        onClick={() => handleAction("reset-device", "reset device limit for")}
        disabled={isLoading}
        className="bg-blue-50 text-blue-600 border border-blue-200 hover:bg-blue-100 font-semibold px-3 py-1.5 rounded-md text-xs transition-colors disabled:opacity-50"
      >
        Reset Devices
      </button>

      <button
        onClick={() => handleAction("resend", "resend email for")}
        disabled={isLoading}
        className="bg-gray-50 text-gray-700 border border-gray-200 hover:bg-gray-100 font-semibold px-3 py-1.5 rounded-md text-xs transition-colors disabled:opacity-50"
      >
        Resend Email
      </button>
    </div>
  );
}

