import { collection, getDocs, query, orderBy, limit, where } from "firebase/firestore";
import { db } from "./firebase";
import { getAuthorsMap } from "./getAuthorAvatar";

type Post = {
  slug: string;
  title: string;
  author?: string;
  created?: string;
  categories?: string[];
  content?: string;
  image?: string;
  featured?: boolean;
  date?: string;
  category?: string;
  excerpt?: string;
  authorAvatar?: string;
};

export async function getServerPosts(page = 1, perPage = 5): Promise<{ posts: Post[]; totalPages: number }> {
  // Parallel Fetching: Start all requests immediately
  const postsQuery = query(collection(db, "posts"), orderBy("createdAt", "desc"), limit(perPage * page + 5));
  const guestQuery = query(collection(db, "guest_posts"), where("status", "==", "approved"), orderBy("submittedAt", "desc"), limit(perPage * page + 5));

  const [postsSnapshot, guestSnapshot, authorsMap] = await Promise.all([
    getDocs(postsQuery),
    getDocs(guestQuery),
    getAuthorsMap()
  ]);

  const postsData: (Post & { createdAt?: string })[] = postsSnapshot.docs.map((doc) => {
    const data = doc.data() as Omit<Post, 'slug'> & { slug?: string, createdAt?: string };
    return {
      ...data,
      slug: data.slug || doc.id,
      createdAt: data.createdAt,
      isGuest: false,
    };
  });

  const guestPosts: (Post & { createdAt?: string; isGuest: boolean; imageUrl?: string })[] = guestSnapshot.docs
    .map((doc) => {
      const data = doc.data() as any;
      return {
        slug: doc.id,
        title: data.title,
        author: data.author,
        created: data.submittedAt,
        category: data.category,
        content: data.content,
        image: data.imageUrl || undefined,
        isGuest: true,
        status: data.status,
      };
    });

  // Merge and sort all posts
  let allPosts = [...postsData, ...guestPosts];
  allPosts.sort((a, b) => {
    const aTime = a.createdAt ? new Date(a.createdAt).getTime() : (a.created ? new Date(a.created).getTime() : 0);
    const bTime = b.createdAt ? new Date(b.createdAt).getTime() : (b.created ? new Date(b.created).getTime() : 0);
    return bTime - aTime;
  });

  // Filter out Hindi posts
  allPosts = allPosts.filter(post => {
    const cats = Array.isArray(post.category) ? post.category : [post.category];
    return !cats.some(cat => cat === 'हिंदी' || cat === 'Hindi');
  });

  // Pagination
  const totalPages = Math.ceil(allPosts.length / perPage);
  const paginated = allPosts.slice((page - 1) * perPage, page * perPage);

  // Assign avatars from the map
  const postsWithAvatars = paginated.map((post) => {
    let avatar = undefined;
    if (post.author) {
      // Try exact match first, then partial match if needed (though map is exact/lowercase)
      avatar = authorsMap[post.author.toLowerCase()];
      if (!avatar) {
        // Fallback: Check if any author in map contains this name (legacy behavior approximation)
        const foundKey = Object.keys(authorsMap).find(k => k.includes(post.author!.toLowerCase()));
        if (foundKey) avatar = authorsMap[foundKey];
      }
    }
    const { createdAt, ...rest } = post;
    return { ...rest, authorAvatar: avatar };
  });

  return { posts: postsWithAvatars, totalPages };
}

const PAYPAL_CLIENT_ID = process.env.PAYPAL_CLIENT_ID!;
const PAYPAL_CLIENT_SECRET = process.env.PAYPAL_CLIENT_SECRET!;
const PAYPAL_ENVIRONMENT = process.env.PAYPAL_ENVIRONMENT || 'sandbox'; // sandbox or live

const base =
  PAYPAL_ENVIRONMENT === 'sandbox'
    ? 'https://api-m.sandbox.paypal.com'
    : 'https://api-m.paypal.com';

/**
 * Generate an OAuth 2.0 access token for authenticating with PayPal REST APIs.
 */
export async function generateAccessToken(): Promise<string> {
  if (!PAYPAL_CLIENT_ID || !PAYPAL_CLIENT_SECRET) {
    throw new Error('MISSING_API_CREDENTIALS');
  }

  const auth = Buffer.from(`${PAYPAL_CLIENT_ID}:${PAYPAL_CLIENT_SECRET}`).toString('base64');
  const response = await fetch(`${base}/v1/oauth2/token`, {
    method: 'POST',
    body: 'grant_type=client_credentials',
    headers: {
      Authorization: `Basic ${auth}`,
    },
  });

  const data = await response.json();
  if (!response.ok) {
    throw new Error(data.error_description || 'Failed to generate access token');
  }
  return data.access_token;
}

/**
 * Create a PayPal order
 * @param amount - The total amount for the order
 * @param currency - The currency code (e.g. USD)
 */
export async function createOrder(amount: string, currency: string = 'USD') {
  const accessToken = await generateAccessToken();
  const url = `${base}/v2/checkout/orders`;

  const payload = {
    intent: 'CAPTURE',
    purchase_units: [
      {
        amount: {
          currency_code: currency,
          value: amount,
        },
      },
    ],
  };

  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${accessToken}`,
    },
    body: JSON.stringify(payload),
  });

  return handleResponse(response);
}

/**
 * Capture a PayPal order
 * @param orderId - The PayPal Order ID to capture
 */
export async function captureOrder(orderId: string) {
  const accessToken = await generateAccessToken();
  const url = `${base}/v2/checkout/orders/${orderId}/capture`;

  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${accessToken}`,
    },
  });

  return handleResponse(response);
}

async function handleResponse(response: Response) {
  try {
    const jsonResponse = await response.json();
    return {
      jsonResponse,
      httpStatusCode: response.status,
    };
  } catch (err) {
    const errorMessage = await response.text();
    throw new Error(errorMessage);
  }
}

/**
 * Verify PayPal Webhook Signature
 */
export async function verifyWebhookSignature(
  transmissionId: string,
  transmissionTime: string,
  certUrl: string,
  authAlgo: string,
  transmissionSig: string,
  webhookEvent: any
) {
  const accessToken = await generateAccessToken();
  const url = `${base}/v1/notifications/verify-webhook-signature`;

  const webhookId = process.env.PAYPAL_WEBHOOK_ID;
  if (!webhookId) {
    throw new Error('PAYPAL_WEBHOOK_ID is not set in environment variables');
  }

  const payload = {
    transmission_id: transmissionId,
    transmission_time: transmissionTime,
    cert_url: certUrl,
    auth_algo: authAlgo,
    transmission_sig: transmissionSig,
    webhook_id: webhookId,
    webhook_event: webhookEvent,
  };

  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${accessToken}`,
    },
    body: JSON.stringify(payload),
  });

  const { jsonResponse, httpStatusCode } = await handleResponse(response);

  if (httpStatusCode !== 200 || jsonResponse.verification_status !== 'SUCCESS') {
    return false;
  }
  return true;
}

import { collection, getDocs, updateDoc, deleteDoc, doc, setDoc, query, where, writeBatch } from "firebase/firestore";
import { db } from "./firebase";
import { products, Product } from "./productsData";
import { Plan } from "../types/license";

export async function getFirestoreProducts(): Promise<Product[]> {
  try {
    const snap = await getDocs(collection(db, "products"));
    if (snap.empty) {
      // Try to populate collection with default products using static ids as document ids
      try {
        const promises = products.map(async (product) => {
          await setDoc(doc(db, "products", product.id), product);
        });
        await Promise.all(promises);

        const newSnap = await getDocs(collection(db, "products"));
        return newSnap.docs.map(d => ({ id: d.id, ...d.data() } as Product));
      } catch (_writeErr) {
        // If write fails (e.g. during build / unauthenticated), return static fallback data
        console.warn("Firestore write denied during auto-initialization, returning static mock data");
        return products;
      }
    }
    return snap.docs.map(d => ({ id: d.id, ...d.data() } as Product));
  } catch (_readErr) {
    console.warn("Firestore read failed, returning static mock data");
    return products;
  }
}

export async function getFirestoreProductById(id: string): Promise<Product | null> {
  try {
    const snap = await getDocs(collection(db, "products"));
    const found = snap.docs.find(d => d.id === id);
    if (!found) {
      // Fallback to static products
      return products.find(p => p.id === id) || null;
    }
    return { id: found.id, ...found.data() } as Product;
  } catch (_err) {
    console.warn("Firestore read by id failed, returning static mock data");
    return products.find(p => p.id === id) || null;
  }
}

export async function addFirestoreProduct(id: string, data: Omit<Product, "id">) {
  return await setDoc(doc(db, "products", id), { ...data, id });
}

export async function updateFirestoreProduct(id: string, data: Omit<Product, "id">) {
  return await updateDoc(doc(db, "products", id), { ...data });
}

export async function deleteFirestoreProduct(id: string) {
  return await deleteDoc(doc(db, "products", id));
}

export async function getPlansForProduct(productId: string): Promise<Plan[]> {
  try {
    const q = query(collection(db, "plans"), where("productId", "==", productId));
    const snap = await getDocs(q);
    return snap.docs.map(d => ({ id: d.id, ...d.data() } as Plan));
  } catch (err) {
    console.error("Failed to fetch plans for product", err);
    return [];
  }
}

export async function savePlansForProduct(productId: string, plans: Partial<Plan>[]) {
  try {
    const batch = writeBatch(db);
    const plansRef = collection(db, "plans");

    const q = query(plansRef, where("productId", "==", productId));
    const snap = await getDocs(q);

    // Delete existing plans for this product to replace with new state
    for (const d of snap.docs) {
      batch.delete(d.ref);
    }

    // Add current plans
    for (const plan of plans) {
      // Use existing id, or fallback to slug or timestamp
      const planId = plan.id || plan.slug || `plan_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`;
      const planDocRef = doc(plansRef, planId); 
      batch.set(planDocRef, {
        ...plan,
        productId,
        updatedAt: new Date().toISOString(),
        createdAt: plan.createdAt || new Date().toISOString()
      });
    }

    await batch.commit();
  } catch (err) {
    console.error("Failed to save plans for product", err);
    throw err;
  }
}
